 const format=0x77c4;for(let i=0;i<15;i++){const bit=!!((format>>>i)&1);m[i<6?i:i<8?i+1:size-15+i][8]=bit;m[8][i<8?size-i-1:i<9?7:14-i]=bit;}m[13][8]=true;
